  "type": "audio_sequence",
  "language": "fon",

  "sequence": [

    /* ================= INTRO ================= */

    {
      "audios": [
        "intro/vous_cherchez_acheter.mp3",
        "produits/mais.mp3",
        "intro/dans_departement.mp3",
        "localites/atlantique.mp3",
        "intro/meilleurs_prix_sont.mp3"
