    {
      "audios": [
        "produits/mais_blanc.mp3",
        "phrases/est_a.mp3",
        "prix/900_fcfa.mp3",
        "unites/kg.mp3",
        "phrases/vendu_a.mp3",
        "prix/4500_fcfa.mp3",
        "unites/bassine_5kg.mp3"
      ],
      "image": "images/produits/mais_blanc_avec_unites.png"
