        "date/releve_le.mp3",
        "date/2026_03_09.mp3"
      ],
      "image": "images/marches/abomey.png"
    },

    {
      "audios": [
        "produits/mais_local.mp3",
        "phrases/est_a.mp3",
        "prix/950_fcfa.mp3",
        "unites/kg.mp3",
        "phrases/vendu_a.mp3",
        "prix/4800_fcfa.mp3",
        "unites/bassine_5kg.mp3"
      ],
      "image": "images/produits/mais_local_avec_unites.png"
    },

    /* ================= MARCHÉ 3 ================= */

    {
      "audios": [
        "ordre/troisieme_marche.mp3",
        "marches/dassa.mp3",
        "date/releve_le.mp3",
        "date/2026_03_08.mp3"
      ],
      "image": "images/marches/dassa.png"
    },

    {
      "audios": [
        "produits/mais_jaune.mp3",
        "phrases/est_a.mp3",
